window.NEXUS.endMeeting=()=>{meetingTitle=null;avatars.forEach(a=>{if(a.state==='desk')return;a.route=[...INNER[a.id].slice().reverse(),[RX-2.5,5.5,'J'],...(a.suite?[[CX+7.5,4.3],[a.home.x,4.3]]:[[19,6.6],[a.home.x,6.6]])].map(toVec).concat([a.home.clone()]);a.routeIndex=0;a.state='return';setActivity(a,'자리로 복귀 중')})};
window.NEXUS.meetingActive=()=>meetingTitle;
function pose(a,seated,walkPhase){const hip=seated?-1.45:0,knee=seated?1.45:0;a.legs.forEach((l,i)=>{l.rotation.x=seated?hip:(walkPhase==null?0:(i?-1:1)*Math.sin(walkPhase)*.6)});a.knees.forEach((k,i)=>{k.rotation.x=seated?knee:(walkPhase==null?0:Math.max(0,(i?-1:1)*Math.sin(walkPhase-1.2))*.9)})}
const ease=x=>x<0?0:x>1?1:x*x*(3-2*x);const pulse=(x,a,b,f=.5)=>ease((x-a)/f)*(1-ease((x-b)/f));
function face(a,t,paused,mode){
 const ph=a.phase;const blink=paused?0:(((t*1.0+ph*1.7)%4.1)<.14?1:0);
 a.eyes.forEach(e=>{e.scale.y=e.userData.sy*(1-blink*.85)*(mode==='focus'?.8:mode==='surprise'?1.25:1);e.scale.x=e.userData.sx*(mode==='happy'?1.05:1)});
 const talk=mode==='talk'?(paused?0:Math.max(0,Math.sin(t*11+ph))*.9+Math.max(0,Math.sin(t*7.3+ph*2))*.5):0;
 a.mouth.scale.set(1+(mode==='happy'?.14:mode==='focus'?-.1:0)+talk*.05,1,1);a.mouth.position.y=a.mouth.userData.y;if(a.mouthOpen){a.mouthOpen.visible=talk>.06;a.mouthOpen.scale.y=.018*Math.max(.25,Math.min(1,talk*.8))}
 a.brows.forEach((b,i)=>{b.position.y=b.userData.y+(mode==='surprise'?.04:mode==='talk'?.015:mode==='focus'?-.012:mode==='happy'?.02:0);b.rotation.z=(i?-1:1)*(mode==='focus'?.12:0)});
}
function setArm(a,i,ux,uz,ex){a.arms[i].rotation.x=ux;a.arms[i].rotation.z=(i?1:-1)*.08+uz;a.elbows[i].rotation.x=ex}
function animateAvatars(t,dt,paused){
 const speaker=avatars.filter(a=>a.state==='meeting');const spk=speaker.length?speaker[Math.floor(t/3.6)%speaker.length]:null;let dirty=false;
 avatars.forEach(a=>{
  const g=a.g,sel=a.selection.visible;const ph=a.phase;
  if(g.userData.workTablet)g.userData.workTablet.visible=sel&&a.state==='desk';
  let phoneOn=false;
  if(a.state==='go'||a.state==='return'){
   const target=a.route[a.routeIndex];const dx=target.x-g.position.x,dz=target.z-g.position.z;const dist=Math.hypot(dx,dz);
   if(!paused){
    if(dist>1e-3){const step=Math.min(dist,4.8*dt),k=step/dist;g.position.x+=dx*k;g.position.z+=dz*k;turnTo(g,Math.atan2(dx,dz),dt*1.6)}
    if(dist<=.06){const cur=a.route[a.routeIndex];a.routeIndex++;if(cur.jump&&a.route[a.routeIndex]){g.position.x=a.route[a.routeIndex].x;g.position.z=a.route[a.routeIndex].z;a.routeIndex++}
     if(a.routeIndex>=a.route.length){if(a.state==='go'){a.state='meeting';setActivity(a,(meetingTitle||'미팅')+' 참석 중');a.faceTarget=a.seatRot}else{a.state='desk';g.position.copy(a.home);setActivity(a,null)}}}
    a.walk=(a.walk||0)+dt*17;
   }
   const w=a.walk||0;pose(a,false,w);const s=Math.sin(w);setArm(a,0,-s*.45,-.04,-.3);setArm(a,1,s*.45,.04,-.3);
   g.position.y=.2+Math.abs(Math.cos(w))*.05;g.rotation.x=.05;g.rotation.z=Math.sin(w)*.02;a.head.rotation.x=-.04;a.head.rotation.y=Math.sin(w*.5)*.05;a.head.rotation.z=0;
   face(a,t,paused,'happy');a.labelPos.set(g.position.x,3.7,g.position.z);
  }else{
   pose(a,true);g.position.y=-.07;g.rotation.z=0;
   const breathe=paused?0:Math.sin(t*1.9+ph)*.01;
   const lookY=paused?0:Math.sin(t*.55+ph)*.06+Math.sin(t*.21+ph*2.7)*.08;
   if(a.state==='desk'){
    turnTo(g,a.homeRot,dt);
    if(!sel||a.id==='jaeho'){
     // Desk work only: typing, reading the monitor, writing memos, thinking. Sales takes phone calls.
     const c=paused?2:((t+ph*3.1)%18);let read=0,memo=0,think=0,phone=0,call=0;
     if(a.id==='chansik'){phone=pulse(c,.5,7,.6)+pulse(c,10.5,15.5,.6);read=pulse(c,7.4,10);think=pulse(c,15.9,17.7)}
     else if(a.isAI){read=pulse(c,5,8.5)+pulse(c,15.5,17.8);think=pulse(c,12,14.5);if(a.id==='ian')call=pulse(c,.8,4.6)+pulse(c,9,11.6)}
     else{read=pulse(c,4.5,7.5);memo=pulse(c,8,11.5);think=pulse(c,14,17)}
     const typing=Math.max(0,1-read-memo-think-phone);
     const key=paused?0:Math.sin(t*12+ph)*.07,key2=paused?0:Math.sin(t*12+ph+2.1)*.07,burst=paused?0:(Math.sin(t*.9+ph)>.2?1:.3);
     const scrib=paused?0:Math.sin(t*9+ph)*.05,scrib2=paused?0:Math.sin(t*6.3+ph)*.03;
     const writeOnCall=phone*(paused?1:(Math.sin(t*.7+ph)>-.2?1:0));const mArm=Math.min(1,memo+writeOnCall);
     // left arm (arms[0]): keyboard / rest / phone to ear
     const Lux=-.4+typing*key*burst,Lex=-.76+typing*key*burst*.6;
     setArm(a,0,Lux*(1-phone)+(-1.75)*phone,(-.02)*(1-phone)+(-.5)*phone,Lex*(1-phone)+(-2.31)*phone);
     // right arm (arms[1]): keyboard / mouse / memo writing
     const Rux=-.4+typing*key2*burst,Rex=-.76+typing*key2*burst*.6;
     setArm(a,1,Rux*(1-mArm)+(-.34)*mArm,.02+read*.1+mArm*(.2+scrib2),Rex*(1-mArm)+(-.86+scrib)*mArm);
     phoneOn=phone>.5;
     g.rotation.x=.05*typing+.1*read+.1*memo-.05*think+.03*phone;
     a.head.rotation.x=.08*typing+.16*read+.34*memo-.14*think+.04*phone+(paused?0:Math.sin(t*.8+ph*1.3)*.02);
     a.head.rotation.y=lookY*typing+.2*memo*(1-phone)+.3*think-.08*phone;
     a.head.rotation.z=.12*phone+.07*think;
     const talkNow=(phone>.5||call>.5)&&(paused||Math.sin(t*.9+ph)>-.35);
     face(a,t,paused,talkNow?'talk':(read>.5||memo>.5||think>.5)?'focus':'neutral');
     const txt=phone>.5?'거래처 통화 중':call>.5?'이어셋 통화 중':memo>.5?'메모 정리 중':think>.5?'골똘히 생각 중':read>.5?'모니터 확인 중':(a.isAI?'데이터 처리 중':'문서 작업 중');
     if(a.activity!==txt){a.activity=txt;dirty=true}
    }else{
     const gest=paused?0:Math.sin(t*2.2+ph);
     setArm(a,0,-.42,-.18,-.9);setArm(a,1,-.42,-.18,-.9+gest*.08);
     g.rotation.x=-.02;a.head.rotation.x=.04+(paused?0:Math.sin(t*3.1+ph)*.03);a.head.rotation.y=(paused?0:Math.sin(t*1.1+ph)*.06);a.head.rotation.z=0;face(a,t,paused,'talk');
     if(a.activity!=='대표님과 대화 중'){a.activity='대표님과 대화 중';dirty=true}
    }
   }else{
    turnTo(g,a.faceTarget??g.rotation.y,dt);
    const talking=spk===a;const gest=paused?0:Math.sin(t*2.4+ph);
    setArm(a,0,-.36,-.04,-.78);
    if(talking){setArm(a,1,-.38,.05+Math.max(0,gest)*.08,-.95+gest*.15);a.head.rotation.x=.02+(paused?0:Math.sin(t*3+ph)*.04);a.head.rotation.y=(paused?0:Math.sin(t*.9+ph)*.2);face(a,t,paused,'talk')}
    else{const agree=paused?0:Math.max(0,Math.sin(t*1.3+ph*2))*Math.max(0,Math.sin(t*.35+ph));setArm(a,1,-.36,.04,-.78);a.head.rotation.x=-.03+agree*.12;a.head.rotation.y=lookY*1.4;face(a,t,paused,agree>.5?'happy':'neutral')}
    g.rotation.x=0;a.head.rotation.z=0;
   }
   g.position.y+=breathe;
   if(a.state==='desk'){const f=a.suite&&a.id==='jaeho'?2.05:1.92;const nd=LABEL_NUDGE[a.id]||[0,0,0];a.labelPos.set(g.position.x+Math.sin(a.homeRot)*f*1.13+nd[0],.98+nd[1],g.position.z+Math.cos(a.homeRot)*f*1.13+nd[2])}else a.labelPos.set(g.position.x,3.28,g.position.z);
  }
  if(a.phoneProp)a.phoneProp.visible=phoneOn;if(a.id==='chansik'&&deskHandset)deskHandset.visible=!phoneOn;
 });
 if(dirty&&!paused)window.NEXUS.renderTasks?.();
}
